--
-- Name: set_sequences_key(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_sequences_key(tablename character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare 

	contador integer;

begin



	UPDATE sequences_key 

	SET    sequence_id  = sequence_id + 1 

	WHERE   table_name = tablename;



	SELECT into contador sequence_id 

	FROM   sequences_key 

	WHERE   table_name = tablename ;



	return contador;

end;

$$;


ALTER FUNCTION public.set_sequences_key(tablename character varying) OWNER TO postgres;

