    id uuid NOT NULL,
    codigo_cliente character varying(255),
    codigo_tipo_documento_identidad integer,
    complemento character varying(10),
    email character varying(255),
    nombre_razon_social character varying(255),
    numero_documento character varying(20),
    state boolean NOT NULL,
    created_by integer DEFAULT 1 NOT NULL,
    created timestamp with time zone DEFAULT now() NOT NULL,
    modified_by integer DEFAULT 1 NOT NULL,
    modified timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE siat.clientes OWNER TO postgres;

