--
-- Name: facturas; Type: TABLE; Schema: siat; Owner: postgres
--

CREATE TABLE siat.facturas (
    id integer NOT NULL,
    cafc character varying(255),
    codigo_cliente character varying(50),
    codigo_documento_sector integer,
    codigo_excepcion integer,
    codigo_metodo_pago integer,
    codigo_moneda integer,
    codigo_punto_venta integer,
    codigo_sucursal integer,
    codigo_tipo_documento_identidad integer,
    complemento character varying(2),
    cuf character varying(100),
    cufd character varying(100),
    cuis character varying(100),
    descuento_adicional numeric(19,2),
    direccion character varying(255),
    email_cliente character varying(255),
    estado character varying(50),
    fecha_emision timestamp without time zone,
    fecha_emision_formato_siat character varying(25) NOT NULL,
    leyenda character varying(300),
    monto_gift_card numeric(19,2),
    monto_total numeric(19,2),
    monto_total_moneda numeric(19,2),
    monto_total_sujeto_iva numeric(19,2),
    municipio character varying(255),
    nit_emisor bigint,
    nombre_razon_social character varying(255),
    numero_documento character varying(255),
    numero_factura bigint,
    numero_tarjeta character varying(50),
    razon_social_emisor character varying(255),
    telefono character varying(255),
    tipo_cambio numeric(19,2),
    usuario character varying(100),
    codigo_emision integer NOT NULL,
    tipo_factura_documento integer NOT NULL,
    codigo_recepcion character varying(40) NOT NULL,
    codigo_evento_significativo integer NOT NULL,
    id_punto_venta uuid,
    state boolean NOT NULL,
    created_by integer NOT NULL,
    created timestamp with time zone NOT NULL,
    modified_by integer NOT NULL,
    modified timestamp with time zone NOT NULL,
    uid uuid NOT NULL,
    nombre_xml character varying(100),
    nombre_sucursal character varying(500)
);


ALTER TABLE siat.facturas OWNER TO postgres;

